create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, bio text, role text not null default 'student' check (role in ('student','coach','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.courses (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, description text, thumbnail_url text, status text not null default 'draft' check (status in ('draft','published','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.course_modules (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id) on delete cascade, title text not null, description text, sort_order integer not null default 0, created_at timestamptz not null default now(), unique(course_id, sort_order));
create table if not exists public.course_lessons (id uuid primary key default gen_random_uuid(), module_id uuid not null references public.course_modules(id) on delete cascade, title text not null, description text, content_url text, content_type text default 'video', sort_order integer not null default 0, is_preview boolean not null default false, created_at timestamptz not null default now(), unique(module_id, sort_order));
create table if not exists public.enrollments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, status text not null default 'active' check (status in ('active','completed','cancelled')), progress_percent numeric(5,2) not null default 0 check (progress_percent between 0 and 100), enrolled_at timestamptz not null default now(), completed_at timestamptz, unique(user_id, course_id));
create table if not exists public.lesson_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, lesson_id uuid not null references public.course_lessons(id) on delete cascade, completed boolean not null default false, completed_at timestamptz, updated_at timestamptz not null default now(), unique(user_id, lesson_id));
create table if not exists public.workshops (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, description text, starts_at timestamptz, ends_at timestamptz, format text, status text not null default 'draft' check (status in ('draft','upcoming','completed','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.workshop_registrations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, workshop_id uuid not null references public.workshops(id) on delete cascade, status text not null default 'registered' check (status in ('registered','attended','cancelled')), registered_at timestamptz not null default now(), unique(user_id, workshop_id));
create table if not exists public.feed_posts (id uuid primary key default gen_random_uuid(), author_id uuid references public.profiles(id) on delete set null, title text, body text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now());
create table if not exists public.conversation_members (conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, primary key(conversation_id,user_id));
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, body text not null, created_at timestamptz not null default now(), read_at timestamptz);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists profiles_updated_at on public.profiles; create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.course_modules enable row level security;
alter table public.course_lessons enable row level security;
alter table public.enrollments enable row level security;
alter table public.lesson_progress enable row level security;
alter table public.workshops enable row level security;
alter table public.workshop_registrations enable row level security;
alter table public.feed_posts enable row level security;
alter table public.notifications enable row level security;
alter table public.conversations enable row level security;
alter table public.conversation_members enable row level security;
alter table public.messages enable row level security;
drop policy if exists profiles_select_own on public.profiles; create policy profiles_select_own on public.profiles for select to authenticated using(id=auth.uid());
drop policy if exists profiles_update_own on public.profiles; create policy profiles_update_own on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists courses_public_read on public.courses; create policy courses_public_read on public.courses for select to anon,authenticated using(status='published');
drop policy if exists modules_public_read on public.course_modules; create policy modules_public_read on public.course_modules for select to anon,authenticated using(exists(select 1 from public.courses c where c.id=course_id and c.status='published'));
drop policy if exists lessons_preview_read on public.course_lessons; create policy lessons_preview_read on public.course_lessons for select to anon,authenticated using(is_preview=true and exists(select 1 from public.course_modules m join public.courses c on c.id=m.course_id where m.id=module_id and c.status='published'));
drop policy if exists enrollments_own on public.enrollments; create policy enrollments_own on public.enrollments for select to authenticated using(user_id=auth.uid());
drop policy if exists progress_own on public.lesson_progress; create policy progress_own on public.lesson_progress for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists workshops_public_read on public.workshops; create policy workshops_public_read on public.workshops for select to anon,authenticated using(status in ('upcoming','completed'));
drop policy if exists registrations_own on public.workshop_registrations; create policy registrations_own on public.workshop_registrations for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists feed_read on public.feed_posts; create policy feed_read on public.feed_posts for select to authenticated using(true);
drop policy if exists notifications_own on public.notifications; create policy notifications_own on public.notifications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists conversation_members_own on public.conversation_members; create policy conversation_members_own on public.conversation_members for select to authenticated using(user_id=auth.uid());
drop policy if exists messages_member_read on public.messages; create policy messages_member_read on public.messages for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=conversation_id and cm.user_id=auth.uid()));
drop policy if exists messages_member_insert on public.messages; create policy messages_member_insert on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members cm where cm.conversation_id=conversation_id and cm.user_id=auth.uid()));
